import { CommonModule } from '@angular/common';
import { Component, TemplateRef, viewChild } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatButtonModule } from '@angular/material/button';
import { MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';

@Component({
  template: `
    <mat-form-field>
      <mat-label>{{ label() + '.label' | transloco }}</mat-label>
      <input
        matInput
        [required]="required()"
        [disabled]="true"
        type="password"
        placeholder="{{ label() + '.placeholder' | transloco }}"
        [formControl]="control"
      />
      <button mat-button *ngIf="!control.disabled" matSuffix (click)="chPass()">Cambiar</button>
      <mat-error *ngFor="let error of errorMessages()">
        {{ label() + '.error.' + error | transloco }}
      </mat-error>
    </mat-form-field>

    <ng-template #changeDialog>
      <h1 mat-dialog-title>Cambiar password</h1>
      <div mat-dialog-content>
        <mat-form-field>
          <mat-label>{{ label() }}</mat-label>
          <input
            matInput
            type="password"
            [required]="true"
            [placeholder]="''"
            [disabled]="control.disabled"
            [(ngModel)]="typed"
            autocomplete="new-password"
          />
        </mat-form-field>
      </div>
      <div mat-dialog-actions>
        <button mat-button mat-dialog-close (click)="close()">Cancelar</button>
        <button mat-button mat-dialog-close (click)="update()" cdkFocusInitial>Cambiar</button>
      </div>
    </ng-template>
  `,
  selector: 'editable-password',
  imports: [
    FormsModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatButtonModule,
    MatDialogModule,
    MatIconModule,
    CommonModule,
    TranslocoModule,
  ],
  providers: BaseEditable.getAccessorProvider(EditablePasswordComponent),
  standalone: true,
})
export class EditablePasswordComponent extends BaseEditable<string> {
  typed = '';

  template = viewChild<TemplateRef<any>>('changeDialog');

  private dialogRef?: MatDialogRef<any>;

  constructor(private dialog: MatDialog) {
    super();
  }

  chPass() {
    const template = this.template();
    if (template) {
      this.dialogRef = this.dialog.open(template);
    } else {
      console.error('No template on the component');
    }
  }

  close() {
    this.dialogRef?.close();
  }

  update() {
    if (this.control) {
      this.control.setValue(this.typed);
      this.control.markAsDirty();
      this.control.updateValueAndValidity();
    }
    this.dialogRef?.close();
  }
}
